import { Column, SchemaIR } from '../../shared/model';

/**
 * Exports a SchemaIR into valid DBML syntax.
 */
export function exportToDbml(schema: SchemaIR): string {
  const lines: string[] = [
    '// Generated by Laravel ERD Viewer',
    `// Migrations applied: ${schema.migrationsApplied.length}`,
    '',
  ];

  // Tables
  for (const table of schema.tables) {
    lines.push(`Table ${table.name} {`);
    for (const col of table.columns) {
      lines.push(`  ${formatDbmlColumn(col)}`);
    }

    // Table-level indexes if any
    const nonPkIndexes = table.indexes.filter((idx) => idx.kind !== 'primary');
    if (nonPkIndexes.length > 0) {
      lines.push('');
      lines.push('  indexes {');
      for (const idx of nonPkIndexes) {
        const colList = idx.columns.length > 1 ? `(${idx.columns.join(', ')})` : idx.columns[0];
        const settings: string[] = [];
        if (idx.kind === 'unique') settings.push('unique');
        if (idx.name) settings.push(`name: '${idx.name}'`);
        const settingStr = settings.length > 0 ? ` [${settings.join(', ')}]` : '';
        lines.push(`    ${colList}${settingStr}`);
      }
      lines.push('  }');
    }

    lines.push('}');
    lines.push('');
  }

  // Relations
  for (const rel of schema.relations) {
    if (rel.to.table === '*') continue; // Skip polymorphic

    const operator = rel.cardinality === '1:1' ? '-' : '>';
    const settings: string[] = [];
    if (rel.onDelete) settings.push(`delete: ${rel.onDelete.replace(/\s+/g, ' ')}`);
    if (rel.onUpdate) settings.push(`update: ${rel.onUpdate.replace(/\s+/g, ' ')}`);

    const settingStr = settings.length > 0 ? ` [${settings.join(', ')}]` : '';
    lines.push(`Ref: ${rel.from.table}.${rel.from.column} ${operator} ${rel.to.table}.${rel.to.column}${settingStr}`);
  }

  return lines.join('\n');
}

function formatDbmlColumn(col: Column): string {
  let typeStr = col.type;
  if (col.length) typeStr += `(${col.length})`;
  else if (col.precision && col.scale) typeStr += `(${col.precision}, ${col.scale})`;

  const settings: string[] = [];
  if (col.primary) settings.push('pk');
  if (col.autoIncrement) settings.push('increment');
  if (col.unique && !col.primary) settings.push('unique');
  if (col.nullable) settings.push('null');
  else if (!col.primary) settings.push('not null');

  if (col.default !== undefined) {
    if (typeof col.default === 'object' && col.default !== null && 'raw' in col.default) {
      settings.push(`default: \`${col.default.raw}\``);
    } else if (typeof col.default === 'string') {
      settings.push(`default: '${col.default}'`);
    } else {
      settings.push(`default: ${col.default}`);
    }
  }

  if (col.comment) {
    settings.push(`note: '${col.comment.replace(/'/g, "\\'")}'`);
  }

  const settingStr = settings.length > 0 ? ` [${settings.join(', ')}]` : '';
  return `${col.name} ${typeStr}${settingStr}`;
}
